package com.projectseele.world;
import com.google.gson.*;import com.projectseele.entity.SiloHatchMechanism;import java.nio.file.*;import java.security.*;import java.util.*;import net.minecraft.world.phys.*;

/** Necessary exact-source64m retreat geometry. Does not enable rails or open a World. */
public final class CheckTerminal84CarrierRetreatR53
{
    private static final Gson G=new GsonBuilder().setPrettyPrinting().create();
    private static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
    private static RigidTransform frame(JsonObject g){var p=g.getAsJsonArray("position");var q=g.getAsJsonArray("quaternion");return new RigidTransform(new Vec3(p.get(0).getAsDouble(),p.get(1).getAsDouble(),p.get(2).getAsDouble()),q.get(0).getAsFloat(),q.get(1).getAsFloat(),q.get(2).getAsFloat(),q.get(3).getAsFloat());}
    public static void main(String[] args)throws Exception
    {
        byte[] raw=Files.readAllBytes(Path.of(args[0])),steel=Files.readAllBytes(Path.of(args[1]));String directorySha=sha(raw),steelSha=sha(steel);var original=JsonParser.parseString(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();var document=original.deepCopy();document.addProperty("status","installed");document.addProperty("installation_receipt_sha256",steelSha);var directory=NervRouteDirectoryR52.parse(document);NervUprightGuidewayR52.install(steel,steelSha,directory);var index=new NervStaticSpatialIndexR52<NervUprightGuidewayR52.RailPiece>(NervUprightGuidewayR52.pieces(),p->p.steel().mesh().envelope(p.steel().frame(),p.steel().frame()));var gateDoc=JsonParser.parseString(Files.readString(Path.of(args[2]))).getAsJsonObject();if(!gateDoc.get("directory_sha256").getAsString().equals(directorySha))throw new AssertionError("Current gate/directory binding changed");var gates=new HashMap<String,JsonObject>();for(var g:gateDoc.getAsJsonArray("gates"))gates.put(g.getAsJsonObject().get("resource").getAsString(),g.getAsJsonObject());var rows=new ArrayList<Object>();var hits=new ArrayList<Object>();
        for(var route:directory.routes().values())if(!route.recovery())
        {
            var leg=directory.leg(route.legs().get(route.legs().size()-1));var binding=NervOriginalCarrierR52.nominalBinding(route.variant());var root=directory.sample(leg,1,binding).evaRoot();var segments=leg.centreCurve().segments();var tail=segments.get(segments.size()-1).controls();var delta=tail.get(tail.size()-1).subtract(tail.get(0));if(tail.size()!=2||delta.horizontalDistanceSqr()>1e-12||delta.y<64)throw new AssertionError("Actual terminal pureV cannot contain full64 source travel");double length=directory.legLength(leg);var curve=new DirectoryTrajectoryR52(directory,leg,binding,(length-64)/length,1);var supportMissing=new ArrayList<Integer>();for(int i=0;i<=64;i++)if(!NervUprightGuidewayR52.finiteCaptureAtR52(curve,i/64D))supportMissing.add(i);
            var A=NervOriginalCarrierR52.partsAtR53(route.variant(),root,0,new Vec3(0,1,0),NervLegacyCarrierRideR52.rest(),new Vec3(0,1,0),0);var M=NervOriginalCarrierR52.partsAtR53(route.variant(),root,.5F,new Vec3(0,1,0),NervLegacyCarrierRideR52.rest(),new Vec3(0,1,0),0);var B=NervOriginalCarrierR52.partsAtR53(route.variant(),root,1,new Vec3(0,1,0),NervLegacyCarrierRideR52.rest(),new Vec3(0,1,0),0);String id="bank_"+route.bank()+"_surface_lane_"+route.lane();var gate=gates.get(id);var spec=gate.getAsJsonObject("silo_hatch");var hatch=NervSiloHatchGeometryR52.loadClasspath(new SiloHatchMechanism.Spec(31,31,spec.get("open_ticks").getAsInt(),spec.get("close_ticks").getAsInt(),1,spec.get("beam_bottom").getAsDouble(),false,true));var gf=frame(gate.getAsJsonObject("frame"));long staticPairs=0;double low=Double.POSITIVE_INFINITY;int before=hits.size();
            for(int i=0;i<A.size();i++){var a=A.get(i);var m=M.get(i);var b=B.get(i);if(!a.name().equals(b.name())||!Arrays.equals(a.mesh().triangles(),b.mesh().triangles())||!Arrays.equals(a.mesh().triangles(),m.mesh().triangles())||a.frame().rotationErrorDegrees(b.frame())>1e-6||m.frame().translation().distanceTo(a.frame().translation().lerp(b.frame().translation(),.5))>1e-7)throw new AssertionError("Actual whole carrier actuator is no longer a rigid affine source: "+a.name());var bounds=a.mesh().envelope(a.frame(),b.frame());low=Math.min(low,bounds.minY);
                for(var fixed:index.query(bounds)){staticPairs++;if(fixed.leg().equals(leg.id())&&NervUprightGuidewayR52.namedCaptureContactR52(a,b,fixed))continue;var f=fixed.steel();if(a.mesh().intersects(a.frame(),b.frame(),f.mesh(),f.frame(),f.frame(),.003,Vec3.ZERO))hits.add(Map.of("route",route.id(),"part",a.name(),"fixed",fixed.name(),"kind","current_actual_static_steel"));}
                for(var part:hatch.pieces(1)){var mesh=new NervRigidMeshSweepR52(part.part().xyz());var f=gf.compose(part.local());if(a.mesh().intersects(a.frame(),b.frame(),mesh,f,f,.003,Vec3.ZERO))hits.add(Map.of("route",route.id(),"part",a.name(),"fixed",id+"/"+part.part().name(),"kind","actual_fully_open_outlet_hatch"));}
            }
            rows.add(Map.of("route",route.id(),"variant",route.variant(),"actual_carrier_parts",A.size(),"terminal_pure_vertical_m",delta.y,"lowest_actual_swept_y",low,"native_ten_face_sample_count",65,"ten_face_missing_at_metre_samples",supportMissing,"actual_static_steel_pairs",staticPairs,"forbidden_mesh_hits",hits.size()-before));System.out.println(route.id()+" parts="+A.size()+" supportMissing="+supportMissing.size()+" hits="+(hits.size()-before));
        }
        var result=new LinkedHashMap<String,Object>();result.put("schema","projectseele.r53.current-terminal84-carrier64-source-check.v1");result.put("directory_sha256",directorySha);result.put("steel_sha256",steelSha);result.put("gate_candidate_sha256",sha(Files.readAllBytes(Path.of(args[2]))));result.put("routes",rows);result.put("forbidden_mesh_hits",hits);result.put("world_written",false);result.put("game_started",false);result.put("world_blocks_checked",false);result.put("native_foundations_verified",false);result.put("supports_complete",false);result.put("native_admission",false);result.put("math_constructor_only_installed_flag_in_memory",true);result.put("note","Exact64m affine source sweep covers both travel directions.65 native finite-face samples are discrete support checks, not a separate proof of complete World foundations. Actual input steel has zero anchors and cannot be enabled; no installation flag was persisted.");Files.writeString(Path.of(args[3]),G.toJson(result));
    }
}
